/**
 * Подтема SddsFinAiTheme.OnDark
 */
@Composable
public fun SddsFinAiTheme.OnDark(
    isDark: Boolean = isSystemInDarkTheme(),
    content: @Composable
    () -> Unit,
) {
    val currentColors = LocalSddsFinAiColors.current
    val overrideColors = currentColors.copyAttrs(OnDarkColorsOverride)
    val currentGradients = LocalSddsFinAiGradients.current
    val overrideGradients = currentGradients.copyAttrs(OnDarkGradientsOverride)
    SddsFinAiTheme(
        colors = overrideColors,
        gradients = overrideGradients,
        content = content,
    )
}
